def compute(vars):
    average_net_loss = (vars["v1"] + vars["v2"]) / 2
    return {
        "value": average_net_loss,
        "trace": {
            "net_loss_2018": vars["v1"],
            "net_loss_2019": vars["v2"],
            "average_net_loss": average_net_loss,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
